<?php
require __DIR__.'/config.php';$me=require_auth();$cid=(int)$me['customer_id'];$uid=(int)$me['id'];$errors=[];$v=$_POST;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'');
    if($action==='apply'){$loanType=trim((string)($_POST['loan_type']??''));$principalRaw=trim((string)($_POST['principal_amount']??''));$duration=filter_var($_POST['duration_months']??null,FILTER_VALIDATE_INT);if($loanType===''||strlen($loanType)>50)$errors[]='Enter a loan purpose or type of 1 to 50 characters.';if(!preg_match('/^\d{1,12}(\.\d{1,2})?$/',$principalRaw)||(float)$principalRaw<=0)$errors[]='Enter a valid loan amount.';if(!$duration||$duration<1||$duration>360)$errors[]='Choose a duration from 1 to 360 months.';if(!$errors){try{$principal=round((float)$principalRaw,2);$monthly=round($principal/(int)$duration,2);$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO loans (loan_type,principal_amount,interest_rate,duration_months,application_date,disbursement_account_id,monthly_installment,outstanding_balance,status,approved_by_user_id) VALUES (?,?,0,?,CURDATE(),NULL,?,0,'pending',NULL)");$s->execute([$loanType,$principal,(int)$duration,$monthly]);$loanId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO loan_parties (loan_id,customer_id,party_role) VALUES (?,?,'borrower')")->execute([$loanId,$cid]);$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'loan_request',?)")->execute([$uid,'Loan application #'.$loanId.' submitted and pending staff review.']);audit($uid,'LOAN_APPLY','loans',$loanId,'Customer submitted a loan application');$pdo->commit();flash('Loan application submitted for staff review.');go('loans.php');}catch(Throwable $x){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$errors[]='We could not submit your loan application. Please check the details and try again.';}}}
    elseif($action==='repay'){$paymentId=filter_var($_POST['payment_id']??null,FILTER_VALIDATE_INT);$accountId=filter_var($_POST['account_id']??null,FILTER_VALIDATE_INT);if(!$paymentId||!$accountId)$errors[]='Select an installment and an account.';else{try{$pdo=db();$pdo->beginTransaction();$accountLock=$pdo->prepare('SELECT account_id,balance,status,account_type_id FROM accounts WHERE account_id=? FOR UPDATE');$accountLock->execute([(int)$accountId]);$account=$accountLock->fetch();if(!$account||$account['status']!=='active'||!owned_account($pdo,$cid,(int)$accountId))throw new RuntimeException();$findLoan=$pdo->prepare('SELECT lp.loan_id FROM loan_payments lp JOIN loan_parties p ON p.loan_id=lp.loan_id WHERE lp.payment_id=? AND p.customer_id=?');$findLoan->execute([(int)$paymentId,$cid]);$loanId=(int)$findLoan->fetchColumn();if(!$loanId)throw new RuntimeException();$loanLock=$pdo->prepare('SELECT loan_id,loan_type,outstanding_balance,status FROM loans WHERE loan_id=? FOR UPDATE');$loanLock->execute([$loanId]);$loan=$loanLock->fetch();$paymentLock=$pdo->prepare('SELECT payment_id,installment_number,scheduled_principal,scheduled_interest,paid_amount,status,related_transaction_id FROM loan_payments WHERE payment_id=? AND loan_id=? FOR UPDATE');$paymentLock->execute([(int)$paymentId,$loanId]);$payment=$paymentLock->fetch();if(!$loan||$loan['status']!=='active'||!$payment||!in_array($payment['status'],['due','overdue','partial'],true)||$payment['related_transaction_id']!==null)throw new RuntimeException();$due=round((float)$payment['scheduled_principal']+(float)$payment['scheduled_interest']-(float)$payment['paid_amount'],2);$principalDue=max(0.0,(float)$payment['scheduled_principal']);$balanceBefore=(float)$account['balance'];$balanceAfter=$balanceBefore-$due;$min=$pdo->prepare('SELECT minimum_balance FROM account_types WHERE account_type_id=?');$min->execute([(int)$account['account_type_id']]);if($due<=0||$balanceAfter+0.00001<(float)$min->fetchColumn())throw new RuntimeException();$ref=null;$check=$pdo->prepare('SELECT 1 FROM transactions WHERE reference_number=?');for($i=0;$i<20;$i++){$candidate='TXN'.date('ymdHis').random_int(100,999);$check->execute([$candidate]);if(!$check->fetchColumn()){$ref=$candidate;break;}}if($ref===null)throw new RuntimeException();$description='Loan repayment — '.$loan['loan_type'].' installment '.$payment['installment_number'];$txn=$pdo->prepare("INSERT INTO transactions (reference_number,account_id,transaction_type,amount,balance_before,balance_after,related_account_id,description,status,performed_by_user_id) VALUES (?,?,'withdrawal',?,?,?,NULL,?,'completed',?)");$txn->execute([$ref,(int)$accountId,$due,$balanceBefore,$balanceAfter,$description,$uid]);$transactionId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE accounts SET balance=? WHERE account_id=?')->execute([$balanceAfter,(int)$accountId]);$pdo->prepare("UPDATE loan_payments SET paid_amount=scheduled_principal+scheduled_interest,paid_date=CURDATE(),status='paid',related_transaction_id=? WHERE payment_id=?")->execute([$transactionId,(int)$paymentId]);$outstanding=max(0.0,(float)$loan['outstanding_balance']-$principalDue);$loanStatus=$outstanding<=0.005?'closed':'active';$pdo->prepare('UPDATE loans SET outstanding_balance=?,status=? WHERE loan_id=?')->execute([$outstanding,$loanStatus,$loanId]);$pdo->commit();flash('Installment paid successfully.');go('transaction.php?id='.$transactionId);}catch(Throwable $x){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$errors[]='The installment could not be paid. Check your account status, minimum balance, and installment status.';}}}
    else $errors[]='Invalid loan request.';
}
$s=db()->prepare('SELECT l.loan_id,l.loan_type,l.principal_amount,l.interest_rate,l.duration_months,l.application_date,l.approval_date,l.monthly_installment,l.outstanding_balance,l.status FROM loans l JOIN loan_parties p ON p.loan_id=l.loan_id WHERE p.customer_id=? ORDER BY l.application_date DESC,l.loan_id DESC');$s->execute([$cid]);$loans=$s->fetchAll();$loanIds=array_map('intval',array_column($loans,'loan_id'));$payments=[];if($loanIds){$marks=implode(',',array_fill(0,count($loanIds),'?'));$s=db()->prepare("SELECT payment_id,loan_id,installment_number,due_date,scheduled_principal,scheduled_interest,paid_amount,paid_date,status,related_transaction_id FROM loan_payments WHERE loan_id IN ($marks) ORDER BY loan_id,installment_number");$s->execute($loanIds);foreach($s->fetchAll() as $p)$payments[(int)$p['loan_id']][]=$p;}
$s=db()->prepare("SELECT a.account_id,a.account_number,a.account_title,a.balance,a.currency,t.minimum_balance FROM account_holders h JOIN accounts a ON a.account_id=h.account_id JOIN account_types t ON t.account_type_id=a.account_type_id WHERE h.customer_id=? AND a.status='active' ORDER BY a.account_id");$s->execute([$cid]);$accounts=$s->fetchAll();render_start('Loans');?>
<section class="page-heading"><div class="eyebrow dark">Planning for what’s next</div><h1>Loans</h1><p>Apply for a loan, review its status, and manage scheduled installments.</p></section><?php if($errors):?><div class="notice error" role="alert"><ul><?php foreach(array_unique($errors) as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?>
<section class="loan-application"><div><div class="eyebrow dark">Start an application</div><h2>Tell us what you need.</h2><p>Applications remain pending until staff review. The database requires provisional pricing fields, so the application stores 0% interest and a simple principal ÷ duration monthly estimate until staff set approved terms. No payment schedule is generated before approval.</p></div><form method="post" class="loan-form"><?=csrf()?><input type="hidden" name="action" value="apply"><div class="field"><label for="loan_type">Loan purpose / type</label><input id="loan_type" name="loan_type" maxlength="50" required value="<?=e($v['loan_type']??'')?>" placeholder="For example, education or renovation"></div><div class="field"><label for="principal_amount">Requested amount (BDT)</label><input id="principal_amount" name="principal_amount" type="number" min="1" max="999999999999.99" step="0.01" required value="<?=e($v['principal_amount']??'')?>"></div><div class="field"><label for="duration_months">Requested duration (months)</label><input id="duration_months" name="duration_months" type="number" min="1" max="360" step="1" required value="<?=e($v['duration_months']??'')?>"></div><button class="button navy" type="submit">Submit loan application</button></form></section>
<div class="section-heading"><h2>Your loans and applications</h2></div><?php if(!$loans):?><div class="empty">You have no loan applications.</div><?php else:foreach($loans as $loan):?><section class="loan-card"><header><div><span class="badge"><?=e(ucfirst($loan['status']))?></span><h2><?=e($loan['loan_type'])?></h2></div><span class="loan-balance">Outstanding<br><strong>BDT <?=e(number_format((float)$loan['outstanding_balance'],2))?></strong></span></header><div class="loan-summary"><span>Requested principal <b>BDT <?=e(number_format((float)$loan['principal_amount'],2))?></b></span><span>Rate <b><?=e(number_format((float)$loan['interest_rate'],2))?>%</b></span><span>Duration <b><?=e((string)$loan['duration_months'])?> months</b></span><span>Monthly installment <b>BDT <?=e(number_format((float)$loan['monthly_installment'],2))?></b></span><span>Applied <b><?=e($loan['application_date'])?></b></span><?php if($loan['approval_date']):?><span>Approved <b><?=e($loan['approval_date'])?></b></span><?php endif;?></div>
<?php if(!empty($payments[(int)$loan['loan_id']])):?><h3>Installment schedule</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Due date</th><th>Principal</th><th>Interest</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($payments[(int)$loan['loan_id']] as $p):$paymentDue=max(0,(float)$p['scheduled_principal']+(float)$p['scheduled_interest']-(float)$p['paid_amount']);?><tr><td><?=e((string)$p['installment_number'])?></td><td><?=e($p['due_date'])?></td><td>BDT <?=e(number_format((float)$p['scheduled_principal'],2))?></td><td>BDT <?=e(number_format((float)$p['scheduled_interest'],2))?></td><td>BDT <?=e(number_format($paymentDue,2))?></td><td><?=e(ucfirst($p['status']))?></td><td><?php if($loan['status']==='active'&&in_array($p['status'],['due','overdue','partial'],true)&&$p['related_transaction_id']===null&&$paymentDue>0&&$accounts):?><form method="post" class="repay-form" onsubmit="return confirm('Pay this installment from the selected account?')"><?=csrf()?><input type="hidden" name="action" value="repay"><input type="hidden" name="payment_id" value="<?=$p['payment_id']?>"><label class="visually-hidden" for="payacct<?=$p['payment_id']?>">Pay from account</label><select name="account_id" id="payacct<?=$p['payment_id']?>" required><option value="">Pay from…</option><?php foreach($accounts as $a):?><option value="<?=$a['account_id']?>"><?=e($a['account_title'])?> · •••• <?=e(substr($a['account_number'],-4))?></option><?php endforeach;?></select><button class="button navy" type="submit">Pay installment</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php elseif(in_array($loan['status'],['pending','approved'],true)):?><p class="muted">No repayment schedule is available until staff finalize and activate the loan terms.</p><?php else:?><p class="muted">No installments are recorded for this loan.</p><?php endif;?></section><?php endforeach;endif;?><?php render_end();?>
